import type { ClassId } from '../character';

/**
 * Talent values an OWNER STATEMENT or a patch note gives and the client has not
 * shipped yet.
 *
 * ============================================================================
 * REBUILT A FOURTH TIME (2026-11-11), for Maelstrom Weapon. It was deleted
 * at 1.60.1.70425, at 1.60.1.70707 and at 1.60.1.70755, each time when the
 * client caught up with every row.
 *
 * `src/data/talents/values/*.json` is GENERATED by matching `{0}` placeholders
 * against each rank's text from `talentsforever.com`, and
 * `import_forever_talents.mjs` merges a previous entry ONLY where this run
 * produced `null` -- which is to say only for a SINGLE-RANK talent. A hand
 * edit to a multi-rank row is silently clobbered by the next `--write`, so a
 * figure that runs ahead of the client has nowhere safe to go in the data.
 *
 * The first version of this file carried three note figures and was deleted
 * when build 1.60.1.70425 shipped all three verbatim -- it announced its own
 * redundancy by failing `patchNoteValues.test.ts`, which is the designed end of
 * every row here. CLAUDE.md: "the shape is worth rebuilding the next time a
 * note runs ahead of the client ... but it must not be kept standing empty".
 *
 * WHAT MAY NOT GO IN HERE: only a VALUE, never a tree SHAPE, and only where
 * every rank is stated.
 * ============================================================================
 */

/** One rank's value: a single number, or a row when the talent states several. */
export type TalentValueRow = number | readonly number[];

export interface PatchNoteValue {
  /** The source's own words, verbatim, so the figure can be re-read against it. */
  readonly note: string;
  /** Where it came from, for the day the client catches up. */
  readonly source: string;
  /** What the generated file says today, so a refresh that changes it is visible. */
  readonly clientSaid: readonly TalentValueRow[];
  /** What the source says. One entry per rank, in rank order. */
  readonly values: readonly TalentValueRow[];
}

/**
 * Keyed by class and then by talent id -- a talent id is unique only WITHIN a
 * class, so a flat record could not attribute an entry.
 */
export const PATCH_NOTE_TALENT_VALUES: Readonly<
  Partial<Record<ClassId, Readonly<Record<string, PatchNoteValue>>>>
> = {
  shaman: {
    /*
     * THE OWNER'S NOTE, 2026-11-11, AHEAD OF BUILD 1.60.1.70888 -- whose
     * foreverchanges.pro capture still reads "by 4%" at rank 1. Two halves:
     * the reduction is 20% per stack at EVERY rank, and the RATE now rises
     * with rank, 6/7/8/9/10 procs a minute "(was 20 times per minute
     * regardless of rank)".
     *
     * THE PPM IS A FOURTH NUMBER ON THE ROW, INDEX 3, and that is a value
     * rather than a shape: the rank count, the tier and the prerequisite are
     * untouched. Indices 0 to 2 keep their meaning -- reduction per stack,
     * stack cap, duration -- so the tooltip's `{0}` reads 20 on the panel and
     * the reaction reads index 3 for its rate.
     */
    maelstrom_weapon: {
      note:
        'Maelstrom Weapon now grants 20% reduced cast time and Mana cost per application at all ranks ' +
        '(was 4/8/12/16/20% reduced cast time and Mana cost), and chance to activate now increases with ' +
        'rank and activates 6/7/8/9/10 times per minute (was 20 times per minute regardless of rank).',
      source: "the ruleset owner's patch note, 2026-11-11; client 1.60.1.70888 has not shipped it",
      clientSaid: [
        [4, 5, 30],
        [8, 5, 30],
        [12, 5, 30],
        [16, 5, 30],
        [20, 5, 30],
      ],
      values: [
        [20, 5, 30, 6],
        [20, 5, 30, 7],
        [20, 5, 30, 8],
        [20, 5, 30, 9],
        [20, 5, 30, 10],
      ],
    },
  },
};

export function patchNoteValue(
  characterClass: ClassId,
  talentId: string,
  rank: number,
): TalentValueRow | undefined {
  const entry = PATCH_NOTE_TALENT_VALUES[characterClass]?.[talentId];
  if (!entry) return undefined;
  return entry.values[rank - 1];
}
